  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maraudeur-Ail&#233;-(Alchimiste).html&quot; title=&quot;Maraudeur ail&#233;&quot;&gt;Maraudeur ail&#233;&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-(Alchimiste).html&quot; title=&quot;M&#233;tamorphe&quot;&gt;M&#233;tamorphe&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Peste-(Alchimiste).html&quot; title=&quot;Porte-peste&quot;&gt;Porte-peste&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Psychonaute-(Alchimiste).html&quot; title=&quot;Psychonaute&quot;&gt;Psychonaute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrobombardier-(Alchimiste).html&quot; title=&quot;Pyrobombardier&quot;&gt;Pyrobombardier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;animateur-(Alchimiste).html&quot; title=&quot;R&#233;animateur&quot;&gt;R&#233;animateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saboteur-(Alchimiste).html&quot; title=&quot;Saboteur&quot;&gt;Saboteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sapeur-Alchimique-(Alchimiste).html&quot; title=&quot;Sapeur alchimique&quot;&gt;Sapeur alchimique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-Alchimique-(Alchimiste).html&quot; title=&quot;Trappeur alchimique&quot;&gt;Trappeur alchimique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vivisectioniste-(Alchimiste).html&quot; title=&quot;Vivisectioniste&quot;&gt;Vivisectioniste&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Le psychonaute utilise ses connaissances pour explorer des &#233;tats de conscience alternatifs ou m&#234;me d’autres plans d’existence.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Voici les caract&#233;ristiques de classe du psychonaute.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bombe&lt;a class=&quot;headeranchor&quot; id=&quot;Bombe_0&quot; href=&quot;#Bombe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#BOMBES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;bombe&lt;/a&gt; du psychonaute inflige des d&#233;g&#226;ts d’un d&#233; de moins que la normale (une bombe ordinaire inflige des d4, les bombes assourdissantes des d3, etc.) En dehors de cela, ce pouvoir remplace le pouvoir standard de &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#bombes&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Alchimiste&lt;/a&gt; de l’alchimiste et fonctionne de la m&#234;me mani&#232;re.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pr&#233;monition&lt;a class=&quot;headeranchor&quot; id=&quot;Pr&#233;monition_1&quot; href=&quot;#Pr&#233;monition_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, le psychonaute ajoute &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Augure.html&quot; title=&quot;Augure&quot;&gt;augure&lt;/a&gt;&lt;/i&gt; &#224; son livre de formules comme extrait de niveau 2 (cet extrait n’a pas besoin de focalisateur divin). Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#RESISTPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;r&#233;sistance au poison&lt;/a&gt; +4.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Perceptions psychiques&lt;a class=&quot;headeranchor&quot; id=&quot;Perceptions_psychiques_2&quot; href=&quot;#Perceptions_psychiques_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 8, le psychonaute ajoute &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Clairaudienceclairvoyance.html&quot; title=&quot;Clairaudience/clairvoyance&quot;&gt;clairaudience/clairvoyance&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Morts.html&quot; title=&quot;Communication avec les morts&quot;&gt;communication avec les morts&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Scrutation.html&quot; title=&quot;D&#233;tection de la scrutation&quot;&gt;d&#233;tection de la scrutation&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scrutation.html&quot; title=&quot;Scrutation&quot;&gt;scrutation&lt;/a&gt;&lt;/i&gt; &#224; son livre de formules comme extraits de niveau 3 (l’extrait de scrutation n’a pas besoin de focalisateur, ni divin ni autre). Quand le psychonaute utilise l’extrait &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Morts.html&quot; title=&quot;Communication avec les morts&quot;&gt;communication avec les morts&lt;/a&gt;&lt;/i&gt;, il peut entendre l’esprit qui s’attarde dans un cadavre mais ne peut pas faire parler le corps d’une voix audible. En dehors de cela, l’extrait fonctionne comme le sort. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#RESISTPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;r&#233;sistance au poison&lt;/a&gt; +6.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Conscience lointaine&lt;a class=&quot;headeranchor&quot; id=&quot;Conscience_lointaine_3&quot; href=&quot;#Conscience_lointaine_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 10, le psychonaute ajoute &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cauchemar.html&quot; title=&quot;Destrier noir, Cauchemar&quot;&gt;cauchemar&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changement-De-Plan.html&quot; title=&quot;Changement de plan&quot;&gt;changement de plan&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-&#192;-Distance.html&quot; title=&quot;Communication &#224; distance&quot;&gt;communication &#224; distance&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lien-T&#233;l&#233;pathique.html&quot; title=&quot;Lien t&#233;l&#233;pathique&quot;&gt;lien t&#233;l&#233;pathique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Projection-Astrale-Mineure.html&quot; title=&quot;Projection astrale mineure&quot;&gt;projection astrale mineure&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Songe.html&quot; title=&quot;Songe&quot;&gt;songe&lt;/a&gt;&lt;/i&gt; &#224; son livre de formules comme extraits de niveau 4 (l’extrait de changement de plan n’a pas besoin de focalisateur). Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#IMMUNITEAUPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;immunit&#233; aux poisons&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pr&#233;monition sup&#233;rieure&lt;a class=&quot;headeranchor&quot; id=&quot;Pr&#233;monition_sup&#233;rieure_4&quot; href=&quot;#Pr&#233;monition_sup&#233;rieure_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 15, le psychonaute ajoute &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moment-De-Prescience.html&quot; title=&quot;Moment de prescience&quot;&gt;moment de prescience&lt;/a&gt;&lt;/i&gt; &#224; son livre de formules comme extrait de niveau 5. Ce pouvoir remplace l’augmentation des d&#233;g&#226;ts de la bombe &#224; ce niveau.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pr&#233;monition supr&#234;me&lt;a class=&quot;headeranchor&quot; id=&quot;Pr&#233;monition_supr&#234;me_5&quot; href=&quot;#Pr&#233;monition_supr&#234;me_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 17, le psychonaute ajoute &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;monition.html&quot; title=&quot;Pr&#233;monition&quot;&gt;pr&#233;monition&lt;/a&gt;&lt;/i&gt; &#224; son livre de formules comme extrait de niveau 6. Ce pouvoir remplace l’augmentation des d&#233;g&#226;ts de la bombe &#224; ce niveau.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;couvertes&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;couvertes_6&quot; href=&quot;#D&#233;couvertes_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les d&#233;couvertes suivantes viennent compl&#233;ter l’arch&#233;type du psychonaute : &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEDECONFUSION&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe de confusion&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEDEDEMENCE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe de d&#233;mence&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#POTIONETERNELLE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;potion &#233;ternelle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#POTIONPROLONGEE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;potion prolong&#233;e&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#RETARDERLEDEPART&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;retarder le d&#233;part&lt;/a&gt;.
